ee:message.ee:set-payload:
%dw 2.0
output application/java
fun shape(x) = x match {
  case o is Object -> {"^class": x.^class default null} ++ (o mapObject (v, k) -> {(k): shape(v)})
  case a is Array -> {"^class": x.^class default null, items: a map shape($)}
  else -> {"^type": typeOf(x) as String, "^class": x.^class default null}
}
var e = payload.event
---
{payloadClass: payload.^class, payloadMime: payload.^mimeType, attributes: attributes,
 shape: shape(payload), keys: keysOf(payload) map ($ as String), eventKeys: keysOf(e) map ($ as String),
 values: e - "CreatedDate" - "CreatedById", createdBy: e.CreatedById,
 replayIdIsPositive: payload.replayId > 0, eventIdLength: sizeOf(payload.eventId default "")}
